package com.xyzbroker.cashoutapp.domain.result_handlimg

import java.math.BigDecimal
import java.time.LocalDate

/** How a cash-out submit ended, from the customer's point of view. */
sealed interface SubmitOutcome {

    /** Request received and processing. The account is debited but nothing is paid yet. */
    data class Received(
        val reference: String,
        val amount: BigDecimal?,
        val currency: String?,
        val estimatedArrival: LocalDate?,
    ) : SubmitOutcome

    /** The service decided not to act. Nothing was debited. */
    data class Refused(
        val reason: CashOutError,
        val correlationId: String? = null,
    ) : SubmitOutcome

    /** The request never reached the service. Nothing was debited. */
    data object NotSent : SubmitOutcome

    /** Money may or may not have moved. Retry with the same idempotency key to learn the outcome. */
    data class Unknown(
        val correlationId: String? = null,
    ) : SubmitOutcome

    /** Money may or may not have moved and a person must resolve it. Do not retry. */
    data class NeedsSupport(
        val supportReference: String?,
        val correlationId: String? = null,
    ) : SubmitOutcome
}

package com.xyzbroker.cashoutapp.data.mapper

import com.xyzbroker.cashoutapp.data.remote.dto.CashOutResponseDto
import com.xyzbroker.cashoutapp.data.remote.dto.ProblemDto
import com.xyzbroker.cashoutapp.data.remote.network.common.NetworkResult
import com.xyzbroker.cashoutapp.domain.result_handlimg.CashOutError
import com.xyzbroker.cashoutapp.domain.result_handlimg.SubmitOutcome
import java.time.LocalDate
import java.time.format.DateTimeParseException

/**
 * Maps a submit call to a customer outcome. Branches on code only, never on detail.
 * Anything the app cannot positively classify is Unknown, because the service may have debited.
 */
fun NetworkResult<CashOutResponseDto>.toSubmitOutcome(): SubmitOutcome = when (this) {
    is NetworkResult.Success -> data.toSubmitOutcome()
    is NetworkResult.HttpError -> toSubmitOutcome()
    is NetworkResult.NoUsableResponse -> SubmitOutcome.Unknown()
    is NetworkResult.NotSent -> SubmitOutcome.NotSent
}

private fun CashOutResponseDto.toSubmitOutcome(): SubmitOutcome = when {
    isSuccess == true && !reference.isNullOrBlank() -> SubmitOutcome.Received(
        reference = reference,
        amount = amount?.toBigDecimalOrNull(),
        currency = currency,
        estimatedArrival = estimatedArrival?.toLocalDateOrNull(),
    )
    // Only the documented legacy code is a known refusal; any other errorCode is not proof nothing moved.
    isSuccess == false && errorCode == CashOutError.WithdrawalFailed.code ->
        SubmitOutcome.Refused(CashOutError.WithdrawalFailed)
    else -> SubmitOutcome.Unknown()
}

private fun NetworkResult.HttpError.toSubmitOutcome(): SubmitOutcome {
    val correlationId = problem?.correlationId
    return when (val error = problem.toCashOutError(retryAfterSeconds)) {
        is CashOutError.WithdrawalNeedsSupport ->
            SubmitOutcome.NeedsSupport(error.supportReference, correlationId)
        // INTERNAL_ERROR, gateway HTML (no problem body) and unrecognized codes: the outcome is not known.
        is CashOutError.InternalError, is CashOutError.Unknown -> SubmitOutcome.Unknown(correlationId)
        else -> SubmitOutcome.Refused(error, correlationId)
    }
}

/** The Retry-After header wins over the body field when both are present. */
internal fun ProblemDto?.toCashOutError(retryAfterHeader: Long? = null): CashOutError =
    when (this?.code) {
        "IDEMPOTENCY_KEY_REQUIRED" -> CashOutError.IdempotencyKeyRequired
        "VALIDATION_ERROR" -> CashOutError.ValidationError(fieldErrors.orEmpty())
        "UNAUTHENTICATED" -> CashOutError.Unauthenticated
        "ACCOUNT_RESTRICTED" -> CashOutError.AccountRestricted
        "ACCOUNT_NOT_FOUND" -> CashOutError.AccountNotFound
        "NOT_FOUND" -> CashOutError.NotFound
        "INTERNAL_ERROR" -> CashOutError.InternalError
        "WITHDRAWAL_NEEDS_SUPPORT" -> CashOutError.WithdrawalNeedsSupport(supportReference)
        "BELOW_MINIMUM" -> CashOutError.BelowMinimum(minimum)
        "INSUFFICIENT_FUNDS" -> CashOutError.InsufficientFunds(maxWithdrawable)
        "IDEMPOTENCY_KEY_REUSED" -> CashOutError.IdempotencyKeyReused
        "RATE_LIMITED" -> CashOutError.RateLimited(retryAfterHeader ?: retryAfterSeconds)
        else -> CashOutError.Unknown(this?.code)
    }

private fun String.toLocalDateOrNull(): LocalDate? = try {
    LocalDate.parse(this)
} catch (e: DateTimeParseException) {
    null
}

