package com.xyzbroker.cashoutapp.data.mapper

import com.xyzbroker.cashoutapp.data.remote.dto.CashOutResponseDto
import com.xyzbroker.cashoutapp.data.remote.dto.ProblemDto
import com.xyzbroker.cashoutapp.data.remote.network.common.NetworkResult
import com.xyzbroker.cashoutapp.domain.result_handlimg.CashOutError
import com.xyzbroker.cashoutapp.domain.result_handlimg.SubmitOutcome
import org.junit.Assert.assertEquals
import org.junit.Test
import java.io.IOException
import java.math.BigDecimal
import java.net.ConnectException
import java.net.SocketTimeoutException
import java.time.LocalDate

class SubmitCashOutMapperTest {

    private fun success(dto: CashOutResponseDto, replayed: Boolean = false) =
        NetworkResult.Success(dto, replayed).toSubmitOutcome()

    private fun http(status: Int, problem: ProblemDto?, retryAfter: Long? = null) =
        NetworkResult.HttpError(status, problem, retryAfter).toSubmitOutcome()

    private val received = CashOutResponseDto(
        isSuccess = true, cashoutId = "id-1", reference = "CO-5A1D0C21", status = "processing",
        amount = "250.00", currency = "USD", estimatedArrival = "2026-10-23",
    )

    @Test
    fun success_isReceivedWithExactAmountAndDate() {
        assertEquals(
            SubmitOutcome.Received("CO-5A1D0C21", BigDecimal("250.00"), "USD", LocalDate.of(2026, 10, 23)),
            success(received),
        )
    }

    @Test
    fun replayedSuccess_isStillReceived() {
        assertEquals(success(received), success(received, replayed = true))
    }

    @Test
    fun successWithUnreadableDate_isReceivedWithoutDate() {
        val outcome = success(received.copy(estimatedArrival = "soon")) as SubmitOutcome.Received
        assertEquals(null, outcome.estimatedArrival)
    }

    @Test
    fun successWithoutReference_isUnknown() {
        assertEquals(SubmitOutcome.Unknown(), success(received.copy(reference = null)))
    }

    @Test
    fun legacyRefusal_isRefused() {
        assertEquals(
            SubmitOutcome.Refused(CashOutError.WithdrawalFailed),
            success(CashOutResponseDto(isSuccess = false, errorCode = "WITHDRAWAL_FAILED")),
        )
    }

    @Test
    fun legacyRefusalWithUnknownCode_isUnknown() {
        assertEquals(SubmitOutcome.Unknown(), success(CashOutResponseDto(isSuccess = false, errorCode = "NEW_CODE")))
    }

    @Test
    fun bodyWithoutIsSuccess_isUnknown() {
        assertEquals(SubmitOutcome.Unknown(), success(CashOutResponseDto()))
    }

    @Test
    fun definitiveRefusals_areRefusedWithExtras() {
        val cases = mapOf(
            ProblemDto(code = "ACCOUNT_RESTRICTED") to CashOutError.AccountRestricted,
            ProblemDto(code = "BELOW_MINIMUM", minimum = BigDecimal("50.00")) to
                CashOutError.BelowMinimum(BigDecimal("50.00")),
            ProblemDto(code = "INSUFFICIENT_FUNDS", maxWithdrawable = BigDecimal("1250.50")) to
                CashOutError.InsufficientFunds(BigDecimal("1250.50")),
            ProblemDto(code = "VALIDATION_ERROR", fieldErrors = mapOf("iban" to "INVALID_IBAN")) to
                CashOutError.ValidationError(mapOf("iban" to "INVALID_IBAN")),
            ProblemDto(code = "VALIDATION_ERROR") to CashOutError.ValidationError(emptyMap()),
            ProblemDto(code = "IDEMPOTENCY_KEY_REQUIRED") to CashOutError.IdempotencyKeyRequired,
            ProblemDto(code = "IDEMPOTENCY_KEY_REUSED") to CashOutError.IdempotencyKeyReused,
            ProblemDto(code = "UNAUTHENTICATED") to CashOutError.Unauthenticated,
            ProblemDto(code = "ACCOUNT_NOT_FOUND") to CashOutError.AccountNotFound,
            ProblemDto(code = "NOT_FOUND") to CashOutError.NotFound,
        )
        cases.forEach { (problem, error) ->
            assertEquals(problem.code, SubmitOutcome.Refused(error), http(422, problem))
        }
    }

    @Test
    fun refusal_keepsCorrelationId() {
        val outcome = http(403, ProblemDto(code = "ACCOUNT_RESTRICTED", correlationId = "c-1"))
        assertEquals(SubmitOutcome.Refused(CashOutError.AccountRestricted, "c-1"), outcome)
    }

    @Test
    fun rateLimited_prefersHeaderThenBody() {
        val problem = ProblemDto(code = "RATE_LIMITED", retryAfterSeconds = 30)
        assertEquals(SubmitOutcome.Refused(CashOutError.RateLimited(12)), http(429, problem, retryAfter = 12))
        assertEquals(SubmitOutcome.Refused(CashOutError.RateLimited(30)), http(429, problem))
    }

    @Test
    fun needsSupport_keepsSupportReference() {
        val problem = ProblemDto(code = "WITHDRAWAL_NEEDS_SUPPORT", supportReference = "SR-1", correlationId = "c-2")
        assertEquals(SubmitOutcome.NeedsSupport("SR-1", "c-2"), http(409, problem))
    }

    @Test
    fun internalError_isUnknown() {
        assertEquals(
            SubmitOutcome.Unknown("c-3"),
            http(500, ProblemDto(code = "INTERNAL_ERROR", correlationId = "c-3")),
        )
    }

    @Test
    fun gatewayHtml_isUnknown() {
        listOf(502, 503, 504).forEach { assertEquals(SubmitOutcome.Unknown(), http(it, problem = null)) }
    }

    @Test
    fun unrecognizedOrMissingCode_isUnknown() {
        assertEquals(SubmitOutcome.Unknown(), http(422, ProblemDto(code = "SOMETHING_NEW")))
        assertEquals(SubmitOutcome.Unknown(), http(400, ProblemDto()))
    }

    @Test
    fun noUsableResponse_isUnknown() {
        assertEquals(
            SubmitOutcome.Unknown(),
            NetworkResult.NoUsableResponse(SocketTimeoutException()).toSubmitOutcome(),
        )
    }

    @Test
    fun notSent_isNotSent() {
        val result: NetworkResult<CashOutResponseDto> = NetworkResult.NotSent(ConnectException() as IOException)
        assertEquals(SubmitOutcome.NotSent, result.toSubmitOutcome())
    }
}

