  if (!json || typeof json !== 'object' || Array.isArray(json)) return { fatal: problem(400, 'VALIDATION_ERROR', 'Body must be an object.') };

  const fieldErrors = {};
  const m = rawBody.match(/"amount"\s*:\s*("(?:[^"\\]|\\.)*"|[^,}\s]+)/);
  let cents = null;
  if (!m || !/^\d+(\.\d{1,2})?$/.test(m[1])) fieldErrors.amount = 'INVALID_AMOUNT';
  else {
    const [whole, frac = ''] = m[1].split('.');
    cents = Number(whole) * 100 + Number(frac.padEnd(2, '0'));
    if (cents <= 0) { fieldErrors.amount = 'INVALID_AMOUNT'; cents = null; }
