  if (name.length < 2 || name.length > 70) fieldErrors.beneficiaryName = 'INVALID_NAME';
  const iban = typeof dest?.iban === 'string' ? dest.iban.replace(/\s+/g, '').toUpperCase() : '';
  if (!validIban(iban)) fieldErrors.iban = 'INVALID_IBAN';
  if (json.reason != null && (typeof json.reason !== 'string' || json.reason.length > 140)) fieldErrors.reason = 'TOO_LONG';

  if (Object.keys(fieldErrors).length) {
    return { fatal: problem(422, 'VALIDATION_ERROR', 'One or more fields are invalid.', { fieldErrors }) };
